add_filter( 'woocommerce_shortcode_products_query', 'perfectpixel_exclude_category_products_shortcode' );

function perfectpixel_exclude_category_products_shortcode( $args ) {
	$ids = wp_parse_id_list( '{{shortcode_excluded_category_ids}}' );
	if ( $ids ) {
		$args['tax_query']   = isset( $args['tax_query'] ) ? (array) $args['tax_query'] : array();
		$args['tax_query'][] = array(
			'taxonomy' => 'product_cat',
			'field'    => 'term_id',
			'terms'    => $ids,
			'operator' => 'NOT IN',
		);
	}
	return $args;
}
